$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-02. READ ONLY.
# The owner's target contract names D:\HermesData\ollama as the store to preserve. A second store
# exists at G:\HermesData\ollama that the resume lane found and nothing has explained. Before this
# lane points a NEW service at D:, it has to answer two questions with evidence rather than
# preference:
#   (a) is D: really the superset, or does G: hold something D: would lose?
#   (b) is D:'s library internally complete -- every blob each manifest references actually present?
# A manifest that references a missing blob lists fine and fails at load time, which would turn into
# a "migration broke the models" report later. Check it now, before it can be blamed on the move.

function Read-Manifests($root) {
    $mdir = Join-Path $root 'models\manifests'
    if (-not (Test-Path $mdir)) { return @() }
    Get-ChildItem $mdir -Recurse -File | ForEach-Object {
        $j = Get-Content $_.FullName -Raw | ConvertFrom-Json
        $digests = @()
        if ($j.config.digest) { $digests += $j.config.digest }
        foreach ($l in $j.layers) { $digests += $l.digest }
        [pscustomobject]@{
            Name    = $_.FullName.Substring($mdir.Length + 1)
            Digests = $digests
            Bytes   = (@($j.layers | Measure-Object -Sum size).Sum)
        }
    }
}

foreach ($root in @('D:\HermesData\ollama', 'G:\HermesData\ollama')) {
    Write-Output "=== INTEGRITY $root ==="
    $blobDir = Join-Path $root 'models\blobs'
    $have = @{}
    if (Test-Path $blobDir) {
        Get-ChildItem $blobDir -File | ForEach-Object { $have[$_.Name] = $_.Length }
    }
    Write-Output "blob_files=$($have.Count)"
    foreach ($m in Read-Manifests $root) {
        $missing = @()
        foreach ($d in $m.Digests) {
            $fn = $d -replace ':', '-'
            if (-not $have.ContainsKey($fn)) { $missing += $fn }
        }
        $status = if ($missing.Count -eq 0) { 'COMPLETE' } else { "MISSING(" + ($missing -join ',') + ")" }
        Write-Output "model=$($m.Name) layers=$($m.Digests.Count) declared_bytes=$($m.Bytes) $status"
    }
}

Write-Output '=== BLOB-SET-DELTA ==='
$dHave = @{}; $gHave = @{}
Get-ChildItem 'D:\HermesData\ollama\models\blobs' -File -ErrorAction SilentlyContinue | ForEach-Object { $dHave[$_.Name] = $_.Length }
Get-ChildItem 'G:\HermesData\ollama\models\blobs' -File -ErrorAction SilentlyContinue | ForEach-Object { $gHave[$_.Name] = $_.Length }
Write-Output "only_in_G:"
$gHave.Keys | Where-Object { -not $dHave.ContainsKey($_) } | ForEach-Object { "  $_ bytes=$($gHave[$_])" }
Write-Output "only_in_D_count=$((@($dHave.Keys | Where-Object { -not $gHave.ContainsKey($_) })).Count)"
Write-Output '=== G-UNIQUE-BLOB-CONTENT ==='
$gHave.Keys | Where-Object { -not $dHave.ContainsKey($_) -and $gHave[$_] -lt 4096 } | ForEach-Object {
    Write-Output "---- $_"
    Get-Content (Join-Path 'G:\HermesData\ollama\models\blobs' $_) -Raw -ErrorAction SilentlyContinue
}
Write-Output '=== MANIFEST-DIFF-SAME-NAMED ==='
foreach ($rel in @('registry.ollama.ai\library\qwen2.5-coder\7b', 'registry.ollama.ai\library\qwen3\4b-instruct', 'registry.ollama.ai\library\williamos-qwen3-4b\64k')) {
    $dp = "D:\HermesData\ollama\models\manifests\$rel"
    $gp = "G:\HermesData\ollama\models\manifests\$rel"
    $dh = if (Test-Path $dp) { (Get-FileHash $dp -Algorithm SHA256).Hash.ToLower() } else { 'ABSENT' }
    $gh = if (Test-Path $gp) { (Get-FileHash $gp -Algorithm SHA256).Hash.ToLower() } else { 'ABSENT' }
    Write-Output "$rel D=$dh G=$gh same=$($dh -eq $gh)"
}

Write-Output '=== WHY-DOES-G-EXIST: DRIVE-LETTER-HISTORY ==='
# The hand-created container bound F:\HermesData\ollama and F: is now a Realtek driver CD-ROM. If the
# NVMe now lettered G: was lettered F: on 2026-08-18, then "F:" and "G:\HermesData\ollama" are the
# same directory seen at two different times -- which would explain the second store completely.
$md = Get-ItemProperty 'HKLM:\SYSTEM\MountedDevices' -ErrorAction SilentlyContinue
foreach ($letter in @('D:', 'F:', 'G:')) {
    $key = "\DosDevices\$letter"
    if ($md.PSObject.Properties.Name -contains $key) {
        $b = $md.$key
        $ascii = ($b | Where-Object { $_ -ge 32 -and $_ -lt 127 } | ForEach-Object { [char]$_ }) -join ''
        Write-Output "$letter -> len=$($b.Length) ascii=$ascii"
    } else { Write-Output "$letter -> NOT_RECORDED" }
}
Write-Output "G_volume_guid=$((Get-Volume -DriveLetter G).UniqueId)"
Write-Output "G_label=$((Get-Volume -DriveLetter G).FileSystemLabel)"
$gp = Get-Partition -DriveLetter G -ErrorAction SilentlyContinue
Write-Output "G_partition_guid=$($gp.Guid) disk=$($gp.DiskNumber)"
Write-Output '=== G-ROOT-CREATION-TIMES ==='
Get-Item 'G:\HermesData' -Force -ErrorAction SilentlyContinue | Select-Object FullName, CreationTimeUtc, LastWriteTimeUtc | Format-List | Out-String
Get-Item 'G:\HermesData\ollama' -Force -ErrorAction SilentlyContinue | Select-Object FullName, CreationTimeUtc, LastWriteTimeUtc | Format-List | Out-String
Get-Item 'D:\HermesData\ollama' -Force -ErrorAction SilentlyContinue | Select-Object FullName, CreationTimeUtc, LastWriteTimeUtc | Format-List | Out-String

Write-Output '=== SYNC-MODELS-TO-FORGE ==='
Write-Output "sha256=$((Get-FileHash 'C:\HermesLab\hermes\sync-models-to-forge.ps1' -Algorithm SHA256).Hash.ToLower())"
Get-Content 'C:\HermesLab\hermes\sync-models-to-forge.ps1' -ErrorAction SilentlyContinue
Write-Output '=== FORGE-SYNC-TASK ==='
$t = Get-ScheduledTask -TaskName 'HermesModelForgeSync' -ErrorAction SilentlyContinue
if ($t) {
    Write-Output "state=$($t.State)"
    $t.Actions | ForEach-Object { "action_exec=$($_.Execute) args=$($_.Arguments)" }
    $t.Triggers | ForEach-Object { "trigger=$($_.CimClass.CimClassName) start=$($_.StartBoundary) enabled=$($_.Enabled)" }
    $i = Get-ScheduledTaskInfo -TaskName 'HermesModelForgeSync'
    Write-Output "last_run=$($i.LastRunTime) last_result=$($i.LastTaskResult) next=$($i.NextRunTime)"
}
Write-Output '=== OTHER-HERMES-TASKS ==='
foreach ($n in @('HermesLabHealth', 'HermesCrossNodeBackupSync', 'HermesVolumeBackup', 'WilliamOS-HERMES-WSL-Keepalive')) {
    $t = Get-ScheduledTask -TaskName $n -ErrorAction SilentlyContinue
    if ($t) {
        $pr = $t.Principal
        Write-Output "$n state=$($t.State) userid=$($pr.UserId) runlevel=$($pr.RunLevel) logontype=$($pr.LogonType)"
        $t.Actions | ForEach-Object { "   exec=$($_.Execute) args=$($_.Arguments)" }
        $t.Triggers | ForEach-Object { "   trigger=$($_.CimClass.CimClassName)" }
    }
}
Write-Output '--- RC ---'
